schema.shape_profile:
@prefix bioschemas: <https://bioschemas.org/terms/> .
@prefix bioschemas_draft: <https://bioschemas.org/draft_terms/> .
@prefix dash: <http://datashapes.org/dash#> .
@prefix dct: <http://purl.org/dc/terms/> .
@prefix form: <https://platform.vhp4safety.nl/model/v1/form#> .
@prefix glossary: <https://vhp4safety.github.io/glossary#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix pbpk: <https://platform.vhp4safety.nl/model/v1/pbpk#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix schema: <https://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix void: <http://rdfs.org/ns/void#> .
@prefix wd: <http://www.wikidata.org/entity/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

pbpk:BiologicalSystem a rdfs:Class ;
    rdfs:label "Biological system" .

pbpk:Calibration a rdfs:Class ;
    rdfs:label "Calibration" .

pbpk:Compartment a rdfs:Class ;
    rdfs:label "Compartment" .

pbpk:Connection a rdfs:Class ;
    rdfs:label "Connection" .

pbpk:Evaluation a rdfs:Class ;
    rdfs:label "Evaluation" .

pbpk:Implementation a rdfs:Class ;
    rdfs:label "Implementation" .

pbpk:Parameter a rdfs:Class ;
    rdfs:label "Parameter" .

pbpk:PerformanceMetric a rdfs:Class ;
    rdfs:label "Performance metric" .

pbpk:SUVAnalysis a rdfs:Class ;
    rdfs:label "Sensitivity, uncertainty or variability analysis" .

<https://platform.vhp4safety.nl/model/v1> a owl:Ontology ;
    rdfs:label "VHP4Safety Virtual Human Platform" ;
    void:uriSpace "https://platform.vhp4safety.nl/" ;
    owl:imports <https://raw.githubusercontent.com/BioSchemas/bioschemas.github.io/e5c27dbd2b1269a79fbe8f26e0173a9dc390aff0/pages/_types/bioschemas_draft_types.jsonld>,
        <https://raw.githubusercontent.com/BioSchemas/bioschemas.github.io/e5c27dbd2b1269a79fbe8f26e0173a9dc390aff0/pages/_types/bioschemas_types.jsonld>,
        <https://raw.githubusercontent.com/VHP4Safety/glossary/34f9389a7f1f0073b67161e1ca6e6a6cf95c7371/glossary.owl>,
        <https://schema.org/version/30.1/schemaorg-current-https.ttl> ;
    sh:declare [ sh:namespace "https://schema.org/"^^xsd:anyURI ;
            sh:prefix "schema" ],
        [ sh:namespace "https://bioschemas.org/draft_terms/"^^xsd:anyURI ;
            sh:prefix "bioschemas_draft" ],
        [ sh:namespace "https://bioschemas.org/terms/"^^xsd:anyURI ;
            sh:prefix "bioschemas" ],
        [ sh:namespace "http://purl.org/dc/terms/"^^xsd:anyURI ;
            sh:prefix "dct" ],
        [ sh:namespace "http://rdfs.org/ns/void#"^^xsd:anyURI ;
            sh:prefix "void" ],
        [ sh:namespace "https://platform.vhp4safety.nl/model/v1/pbpk#"^^xsd:anyURI ;
            sh:prefix "pbpk" ],
        [ sh:namespace "https://platform.vhp4safety.nl/model/v1/form#"^^xsd:anyURI ;
            sh:prefix "form" ] ;
    sh:shapesGraph <https://raw.githubusercontent.com/BioSchemas/bioschemas.github.io/99beab94c4da4de3ea092b799356a8d05a74a926/pages/_profiles/bioschemas_profiles_shacl.ttl> .

form:AboutPage a sh:NodeShape ;
    rdfs:label "About page" ;
    sh:node form:WebPage ;
    sh:property [ sh:class schema:Organization ;
            sh:description "Its description, videos, figures, research lines, grants and partners are shown, and the publications of its grants." ;
            sh:maxCount 1 ;
            sh:name "About" ;
            sh:order 6 ;
            sh:path schema:mainEntity ] ;
    sh:targetClass schema:AboutPage .

form:ChemicalSubstance a sh:NodeShape ;
    rdfs:label "Chemical substance" ;
    dct:conformsTo <https://bioschemas.org/profiles/ChemicalSubstance/0.4-RELEASE> ;
    sh:node form:Compound ;
    sh:targetClass schema:ChemicalSubstance .

form:Course a sh:NodeShape ;
    rdfs:label "Course" ;
    dct:conformsTo <https://bioschemas.org/profiles/Course/1.0-RELEASE> ;
    sh:node form:LearningResource ;
    sh:property [ sh:name "Provider" ;
            sh:or ( [ rdfs:label "Organisation" ;
                        sh:class schema:Organization ] [ rdfs:label "Person" ;
                        sh:class schema:Person ] ) ;
            sh:order 22 ;
            sh:path schema:provider ],
        [ sh:datatype xsd:string ;
            sh:name "Prerequisites of the course" ;
            sh:order 23 ;
            sh:path schema:coursePrerequisites ],
        [ sh:class schema:CourseInstance ;
            sh:description "Each time the course was given, with its dates and place." ;
            sh:name "Given" ;
            sh:node form:CourseInstance ;
            sh:nodeKind sh:BlankNode ;
            sh:order 24 ;
            sh:path schema:hasCourseInstance ] ;
    sh:targetClass schema:Course .

form:DataCatalog a sh:NodeShape ;
    rdfs:label "Platform" ;
    dct:conformsTo <https://bioschemas.org/profiles/DataCatalog/0.3-RELEASE-2019_07_01> ;
    sh:order 12 ;
    sh:property [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:message "One name needed." ;
            sh:minCount 1 ;
            sh:name "Name" ;
            sh:order 1 ;
            sh:path schema:name ],
        [ sh:datatype xsd:string ;
            sh:description "The name as the home page heads it." ;
            sh:maxCount 1 ;
            sh:name "Heading" ;
            sh:order 2 ;
            sh:path schema:alternateName ],
        [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:name "In one sentence" ;
            sh:order 3 ;
            sh:path schema:abstract ],
        [ dash:singleLine false ;
            sh:maxCount 1 ;
            sh:name "Description" ;
            sh:or ( form:PlainText form:HTMLText ) ;
            sh:order 4 ;
            sh:path schema:description ],
        [ sh:class schema:Organization ;
            sh:description "Its partners are the platform's contributors." ;
            sh:maxCount 1 ;
            sh:message "Add who publishes the platform." ;
            sh:minCount 1 ;
            sh:name "Publisher" ;
            sh:order 5 ;
            sh:path schema:publisher ;
            sh:severity sh:Warning ],
        [ sh:class schema:DefinedTerm ;
            sh:maxCount 1 ;
            sh:message "Choose the licence of the platform's records; none is stated until then." ;
            sh:minCount 1 ;
            sh:name "Licence of the records" ;
            sh:order 6 ;
            sh:path schema:license ;
            sh:pattern "^https://spdx\\.org/licenses/" ;
            sh:severity sh:Warning ;
            form:publishedAs schema:CreativeWork ],
        [ sh:class schema:WebPage ;
            sh:name "Pages about it" ;
            sh:order 7 ;
            sh:path schema:subjectOf ],
        [ sh:description "Each kind's name and description, as the home page shows them; their counts are added." ;
            sh:name "Kinds of records" ;
            sh:node form:ClassPartition ;
            sh:nodeKind sh:BlankNode ;
            sh:order 8 ;
            sh:path void:classPartition ] ;
    sh:targetClass schema:DataCatalog ;
    form:path "platform" .

form:Dataset a sh:NodeShape ;
    rdfs:label "Dataset" ;
    dct:conformsTo <https://bioschemas.org/profiles/Dataset/1.0-RELEASE> ;
    sh:order 5 ;
    sh:property [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:message "One title needed." ;
            sh:minCount 1 ;
            sh:name "Title" ;
            sh:order 1 ;
            sh:path schema:name ],
        [ dash:singleLine false ;
            sh:maxCount 1 ;
            sh:name "Description" ;
            sh:or ( form:PlainText form:HTMLText ) ;
            sh:order 2 ;
            sh:path schema:description ],
        [ sh:name "Authors" ;
            sh:or ( [ rdfs:label "Person" ;
                        sh:class schema:Person ] [ rdfs:label "Organisation" ;
                        sh:class schema:Organization ] ) ;
            sh:order 3 ;
            sh:path schema:creator ],
        [ sh:datatype xsd:date ;
            sh:maxCount 1 ;
            sh:name "Published" ;
            sh:order 4 ;
            sh:path schema:datePublished ],
        [ sh:in ( glossary:VHP0000153 glossary:VHP0000154 glossary:VHP0000155 glossary:VHP0000156 glossary:VHP0000158 ) ;
            sh:message "Choose from the list; other values are not in the filters." ;
            sh:name "Assessment steps" ;
            sh:nodeKind sh:IRI ;
            sh:order 5 ;
            sh:path glossary:VHP0000152 ;
            sh:severity sh:Warning ],
        [ sh:class schema:HowTo ;
            sh:name "Case-study questions" ;
            sh:order 6 ;
            sh:path glossary:VHP0000151 ],
        [ sh:class bioschemas_draft:Study ;
            sh:description "Case studies the data was made for." ;
            sh:name "Case studies" ;
            sh:order 6 ;
            sh:path schema:isPartOf ],
        [ sh:class schema:DefinedTerm ;
            sh:description "What the data is about, such as the organism." ;
            sh:message "Choose a vocabulary term, or register it." ;
            sh:name "Topics" ;
            sh:order 7 ;
            sh:path schema:about ;
            sh:severity sh:Warning ],
        [ sh:class bioschemas_draft:LabProtocol ;
            sh:description "Methods the data was measured with." ;
            sh:name "Methods" ;
            sh:order 8 ;
            sh:path schema:measurementMethod ],
        [ sh:class schema:DefinedTerm ;
            sh:description "Assays the data was measured with, as terms of BAO or other ontologies." ;
            sh:message "Choose a term, such as from BAO, or register it." ;
            sh:name "Assays" ;
            sh:order 9 ;
            sh:path schema:measurementTechnique ;
            sh:severity sh:Warning ],
        [ sh:class schema:ScholarlyArticle ;
            sh:name "Publications" ;
            sh:order 10 ;
            sh:path schema:citation ],
        [ sh:class schema:DefinedTerm ;
            sh:maxCount 1 ;
            sh:message "Add the license, chosen from SPDX; other values are kept." ;
            sh:minCount 1 ;
            sh:name "License" ;
            sh:order 11 ;
            sh:path schema:license ;
            sh:pattern "^https://spdx\\.org/licenses/" ;
            sh:severity sh:Warning ;
            form:publishedAs schema:CreativeWork ],
        [ sh:description "The BioStudies or Zenodo record this one is made from, every night." ;
            sh:maxCount 1 ;
            sh:name "Source record" ;
            sh:nodeKind sh:IRI ;
            sh:order 12 ;
            sh:path schema:isBasedOn ],
        [ sh:name "DOI and other addresses" ;
            sh:nodeKind sh:IRI ;
            sh:order 13 ;
            sh:path schema:sameAs ],
        [ sh:class schema:DefinedTerm ;
            sh:message "Choose a vocabulary term, or register it; text is kept until then." ;
            sh:name "Keywords" ;
            sh:order 14 ;
            sh:path schema:keywords ;
            sh:severity sh:Warning ] ;
    sh:targetClass schema:Dataset ;
    form:path "data" .

form:DefinedTerm a sh:NodeShape ;
    rdfs:label "Term" ;
    dct:conformsTo <https://bioschemas.org/profiles/DefinedTerm/0.1-DRAFT> ;
    sh:order 9 ;
    sh:property [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:message "One label needed." ;
            sh:minCount 1 ;
            sh:name "Label" ;
            sh:order 1 ;
            sh:path schema:name ],
        [ sh:class schema:DefinedTermSet ;
            sh:maxCount 1 ;
            sh:message "One vocabulary needed." ;
            sh:minCount 1 ;
            sh:name "Vocabulary" ;
            sh:order 2 ;
            sh:path schema:inDefinedTermSet ],
        [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:name "Code" ;
            sh:order 3 ;
            sh:path schema:termCode ],
        [ sh:datatype xsd:string ;
            sh:description "Such as a short name." ;
            sh:name "Other names" ;
            sh:order 5 ;
            sh:path schema:alternateName ],
        [ sh:description "The same term in another vocabulary, or another address, such as a license's text." ;
            sh:name "Other addresses" ;
            sh:or ( [ rdfs:label "Term" ;
                        sh:class schema:DefinedTerm ] [ rdfs:label "Address" ;
                        sh:nodeKind sh:IRI ] ) ;
            sh:order 6 ;
            sh:path schema:sameAs ],
        [ dash:singleLine false ;
            sh:maxCount 1 ;
            sh:name "Definition" ;
            sh:or ( form:PlainText form:HTMLText ) ;
            sh:order 4 ;
            sh:path schema:description ] ;
    sh:targetClass schema:DefinedTerm ;
    form:path "terms" .

form:DefinedTermSet a sh:NodeShape ;
    rdfs:label "Vocabulary" ;
    sh:order 10 ;
    sh:property [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:message "One name needed." ;
            sh:minCount 1 ;
            sh:name "Name" ;
            sh:order 1 ;
            sh:path schema:name ],
        [ sh:datatype xsd:string ;
            sh:description "The start of its terms' addresses, when they share one." ;
            sh:maxCount 1 ;
            sh:message "One web address start, such as http://purl.obolibrary.org/obo/NCBITaxon_." ;
            sh:name "Namespace" ;
            sh:order 2 ;
            sh:path void:uriSpace ;
            sh:pattern "^https?://" ],
        [ sh:maxCount 1 ;
            sh:name "Home page" ;
            sh:nodeKind sh:IRI ;
            sh:order 3 ;
            sh:path schema:url ],
        [ sh:description "Its own address elsewhere, such as its Wikidata item." ;
            sh:name "Same as" ;
            sh:nodeKind sh:IRI ;
            sh:order 4 ;
            sh:path schema:sameAs ],
        [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:name "Description" ;
            sh:order 5 ;
            sh:path schema:description ],
        [ sh:description "The terms that records link to are published with it, under this license." ;
            sh:maxCount 1 ;
            sh:message "Add the license of its terms: an SPDX license, or the address of its terms of use." ;
            sh:minCount 1 ;
            sh:name "License" ;
            sh:nodeKind sh:IRI ;
            sh:order 6 ;
            sh:path schema:license ;
            sh:severity sh:Warning ] ;
    sh:targetClass schema:DefinedTermSet ;
    form:path "vocabularies" .

form:LabProtocol a sh:NodeShape ;
    rdfs:label "Method" ;
    dct:conformsTo <https://bioschemas.org/profiles/LabProtocol/0.8-DRAFT> ;
    rdfs:comment "Methods state their Bioschemas profile (LabProtocol)." ;
    sh:order 2 ;
    sh:property [ sh:description "Process flow steps the method informs." ;
            sh:group form:method ;
            sh:in ( glossary:VHP0000153 glossary:VHP0000154 glossary:VHP0000155 glossary:VHP0000156 glossary:VHP0000158 ) ;
            sh:message "Choose from the list; other values are not in the filters." ;
            sh:name "Assessment steps" ;
            sh:nodeKind sh:IRI ;
            sh:order 3 ;
            sh:path glossary:VHP0000152 ;
            sh:severity sh:Warning ],
        [ sh:class schema:HowTo ;
            sh:description "Case study questions the method informs." ;
            sh:group form:method ;
            sh:name "Case-study questions" ;
            sh:order 4 ;
            sh:path glossary:VHP0000151 ],
        [ sh:class schema:DefinedTerm ;
            sh:description "AOP-Wiki key events and pathways the method measures, and glossary terms." ;
            sh:group form:method ;
            sh:message "Choose a term, such as an AOP-Wiki key event, or register it." ;
            sh:name "Key events, pathways and topics" ;
            sh:order 5 ;
            sh:path schema:about ;
            sh:severity sh:Warning ],
        [ sh:class schema:DefinedTerm ;
            sh:description "The kind of assay, as OBI or BAO terms." ;
            sh:group form:method ;
            sh:message "Choose a term, such as from BAO or OBI, or register it." ;
            sh:name "Kind of assay" ;
            sh:order 6 ;
            sh:path schema:additionalType ;
            sh:severity sh:Warning ],
        [ sh:datatype xsd:string ;
            sh:description "The assay or kit name, as its vendor gives it." ;
            sh:group form:assay ;
            sh:maxCount 1 ;
            sh:name "Assay name" ;
            sh:order 1 ;
            sh:path schema:alternateName ],
        [ sh:class schema:Organization ;
            sh:description "The company that sells the assay or kit." ;
            sh:group form:assay ;
            sh:name "Vendor" ;
            sh:order 2 ;
            sh:path schema:provider ],
        [ sh:datatype xsd:string ;
            sh:description "The vendor's catalogue number." ;
            sh:group form:assay ;
            sh:maxCount 1 ;
            sh:name "Catalogue number" ;
            sh:order 3 ;
            sh:path schema:identifier ],
        [ sh:description "The vendor's page." ;
            sh:group form:assay ;
            sh:maxCount 1 ;
            sh:name "Product page" ;
            sh:nodeKind sh:IRI ;
            sh:order 4 ;
            sh:path schema:url ],
        [ sh:description "Who produces data with the method in VHP4Safety." ;
            sh:group form:people ;
            sh:name "Data producer" ;
            sh:or ( [ rdfs:label "Person" ;
                        sh:class schema:Person ] [ rdfs:label "Organisation" ;
                        sh:class schema:Organization ] ) ;
            sh:order 1 ;
            sh:path schema:creator ],
        [ sh:class schema:ScholarlyArticle ;
            sh:description "Publications on the method; their pages link to their DOIs." ;
            sh:group form:documentation ;
            sh:name "Publications" ;
            sh:order 1 ;
            sh:path schema:citation ],
        [ sh:description "The protocol the lab follows." ;
            sh:group form:documentation ;
            sh:name "Standard operating procedure" ;
            sh:nodeKind sh:IRI ;
            sh:order 2 ;
            sh:path schema:subjectOf ],
        [ sh:description "The cloud catalogue request the record was made from." ;
            sh:group form:elsewhere ;
            sh:name "Catalogue request" ;
            sh:nodeKind sh:IRI ;
            sh:order 1 ;
            sh:path schema:isBasedOn ],
        [ sh:datatype xsd:string ;
            sh:description "As known in the lab." ;
            sh:group form:method ;
            sh:maxCount 1 ;
            sh:message "One name needed." ;
            sh:minCount 1 ;
            sh:name "Name" ;
            sh:order 1 ;
            sh:path schema:name ],
        [ dash:singleLine false ;
            sh:description "What the method measures or shows, in one or two sentences." ;
            sh:group form:method ;
            sh:maxCount 1 ;
            sh:name "Description" ;
            sh:or ( form:PlainText form:HTMLText ) ;
            sh:order 2 ;
            sh:path schema:description ] ;
    sh:targetClass bioschemas_draft:LabProtocol ;
    form:path "methods" .

form:MonetaryGrant a sh:NodeShape ;
    rdfs:label "Grant" ;
    sh:order 11 ;
    sh:property [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:message "One name needed." ;
            sh:minCount 1 ;
            sh:name "Name" ;
            sh:order 1 ;
            sh:path schema:name ],
        [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:name "Grant number" ;
            sh:order 2 ;
            sh:path schema:identifier ],
        [ sh:class schema:Organization ;
            sh:message "Add the funder." ;
            sh:minCount 1 ;
            sh:name "Funder" ;
            sh:order 3 ;
            sh:path schema:funder ;
            sh:severity sh:Warning ],
        [ sh:class schema:MonetaryAmount ;
            sh:maxCount 1 ;
            sh:name "Amount" ;
            sh:node form:MonetaryAmount ;
            sh:nodeKind sh:BlankNode ;
            sh:order 4 ;
            sh:path schema:amount ],
        [ sh:description "The funder's page of the grant." ;
            sh:maxCount 1 ;
            sh:name "Page" ;
            sh:nodeKind sh:IRI ;
            sh:order 5 ;
            sh:path schema:url ],
        [ dash:singleLine false ;
            sh:maxCount 1 ;
            sh:name "Description" ;
            sh:or ( form:PlainText form:HTMLText ) ;
            sh:order 6 ;
            sh:path schema:description ] ;
    sh:targetClass schema:MonetaryGrant ;
    form:path "grants" .

form:Person a sh:NodeShape ;
    rdfs:label "Person" ;
    dct:conformsTo <https://bioschemas.org/profiles/Person/0.3-DRAFT> ;
    sh:order 7 ;
    sh:property [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:message "One name needed." ;
            sh:minCount 1 ;
            sh:name "Name" ;
            sh:order 1 ;
            sh:path schema:name ],
        [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:name "Email address" ;
            sh:order 2 ;
            sh:path schema:email ;
            form:private true ],
        [ sh:description "ORCID iD or Wikidata item, as a web address." ;
            sh:name "Elsewhere" ;
            sh:nodeKind sh:IRI ;
            sh:order 3 ;
            sh:path schema:sameAs ],
        [ sh:class schema:Organization ;
            sh:name "Affiliation" ;
            sh:order 4 ;
            sh:path schema:affiliation ] ;
    sh:targetClass schema:Person ;
    form:path "people" .

form:ScholarlyArticle a sh:NodeShape ;
    rdfs:label "Publication" ;
    dct:conformsTo <https://bioschemas.org/profiles/ScholarlyArticle/0.3-DRAFT> ;
    sh:order 4 ;
    sh:property [ sh:maxCount 1 ;
            sh:name "Title" ;
            sh:or ( form:PlainText form:HTMLText ) ;
            sh:order 1 ;
            sh:path schema:name ],
        [ sh:name "Authors" ;
            sh:or ( [ rdfs:label "Person" ;
                        sh:class schema:Person ] [ rdfs:label "Organisation" ;
                        sh:class schema:Organization ] ) ;
            sh:order 2 ;
            sh:path schema:author ],
        [ sh:description "A date, a month or a year, as precise as the publisher gives it." ;
            sh:maxCount 1 ;
            sh:name "Published" ;
            sh:or ( [ rdfs:label "Date" ;
                        sh:datatype xsd:date ] [ rdfs:label "Month" ;
                        sh:datatype xsd:gYearMonth ] [ rdfs:label "Year" ;
                        sh:datatype xsd:gYear ] ) ;
            sh:order 3 ;
            sh:path schema:datePublished ],
        [ sh:class schema:Periodical ;
            sh:maxCount 1 ;
            sh:name "Journal" ;
            sh:node form:Periodical ;
            sh:nodeKind sh:BlankNode ;
            sh:order 4 ;
            sh:path schema:isPartOf ],
        [ sh:description "The DOI as a web address, the Wikidata item, and other addresses." ;
            sh:message "DOI needed, starting with https://doi.org/10." ;
            sh:minCount 1 ;
            sh:name "DOI and other addresses" ;
            sh:nodeKind sh:IRI ;
            sh:order 5 ;
            sh:path schema:sameAs ],
        [ sh:class schema:MonetaryGrant ;
            sh:description "The grants it acknowledges; a project's page lists the publications of its grants." ;
            sh:name "Funded by" ;
            sh:order 6 ;
            sh:path schema:funding ] ;
    sh:targetClass schema:ScholarlyArticle ;
    form:path "publications" .

form:SoftwareApplication a sh:NodeShape ;
    rdfs:label "Tool" ;
    dct:conformsTo <https://bioschemas.org/profiles/ComputationalTool/1.0-RELEASE> ;
    rdfs:comment "Tools state their Bioschemas profile (ComputationalTool)." ;
    sh:order 1 ;
    sh:property [ sh:datatype xsd:string ;
            sh:description "As its developers write it." ;
            sh:group form:about ;
            sh:maxCount 1 ;
            sh:message "One name needed." ;
            sh:minCount 1 ;
            sh:name "Name" ;
            sh:order 1 ;
            sh:path schema:name ],
        [ dash:singleLine false ;
            sh:description "What the tool does, in two or three sentences. Shown in the catalogue and on the tool's page." ;
            sh:group form:about ;
            sh:maxCount 1 ;
            sh:message "One description needed." ;
            sh:minCount 1 ;
            sh:name "Description" ;
            sh:or ( form:PlainText form:HTMLText ) ;
            sh:order 2 ;
            sh:path schema:description ],
        [ sh:description "Website or documentation." ;
            sh:group form:about ;
            sh:maxCount 1 ;
            sh:message "Add the website, if any." ;
            sh:minCount 1 ;
            sh:name "Website" ;
            sh:nodeKind sh:IRI ;
            sh:order 3 ;
            sh:path schema:url ;
            sh:severity sh:Warning ],
        [ sh:description "Where the tool runs, if not its website. Linked as \"Run the tool\"." ;
            sh:group form:about ;
            sh:maxCount 1 ;
            sh:name "Where to use it" ;
            sh:nodeKind sh:IRI ;
            sh:order 4 ;
            sh:path schema:installUrl ],
        [ sh:description "Shown on the tool's card in the catalogue." ;
            sh:group form:about ;
            sh:maxCount 1 ;
            sh:name "Logo or screenshot" ;
            sh:nodeKind sh:IRI ;
            sh:order 5 ;
            sh:path schema:image ],
        [ sh:description "Process flow steps the tool supports; the catalogue is filtered by them." ;
            sh:group form:about ;
