        [ sh:datatype xsd:string ;
            sh:in ( "tutorial" "video" "course" "slides" "notebook" "handout" "e-learning" ) ;
            sh:message "Choose from the list; other values are kept." ;
            sh:name "Kind of material" ;
            sh:order 4 ;
            sh:path schema:learningResourceType ;
            sh:severity sh:Warning ],
        [ sh:message "Link the tools, methods, data or models it teaches." ;
            sh:minCount 1 ;
            sh:name "Tools and methods taught" ;
            sh:or ( [ rdfs:label "Tool" ;
                        sh:class schema:SoftwareApplication ] [ rdfs:label "Method" ;
                        sh:class bioschemas_draft:LabProtocol ] [ rdfs:label "Data" ;
                        sh:class schema:Dataset ] [ rdfs:label "Model" ;
                        sh:class schema:SoftwareSourceCode ] ) ;
            sh:order 5 ;
            sh:path schema:mentions ;
            sh:severity sh:Warning ],
        [ sh:class schema:DefinedTerm ;
            sh:description "What it is about, such as EDAM topics." ;
            sh:message "Choose an ontology term, or register it." ;
            sh:name "Topics" ;
            sh:order 6 ;
            sh:path schema:about ;
            sh:severity sh:Warning ],
        [ sh:description "Where the material is read or watched." ;
            sh:maxCount 1 ;
            sh:name "Address" ;
            sh:nodeKind sh:IRI ;
            sh:order 7 ;
            sh:path schema:url ],
        [ sh:class schema:DefinedTerm ;
            sh:maxCount 1 ;
            sh:message "Add the license, chosen from SPDX; other values are kept." ;
            sh:minCount 1 ;
            sh:name "License" ;
            sh:order 8 ;
            sh:path schema:license ;
            sh:pattern "^https://spdx\\.org/licenses/" ;
            sh:severity sh:Warning ;
            form:publishedAs schema:CreativeWork ],
        [ sh:datatype xsd:string ;
            sh:description "An IETF BCP 47 code, such as en; English when none is given." ;
            sh:name "Language" ;
            sh:order 9 ;
            sh:path schema:inLanguage ],
        [ sh:datatype xsd:string ;
            sh:description "An ISO 8601 duration, such as PT1H30M." ;
            sh:maxCount 1 ;
            sh:name "Time required" ;
            sh:order 10 ;
            sh:path schema:timeRequired ;
            sh:pattern "^P" ],
        [ sh:datatype xsd:string ;
            sh:in ( "Beginner" "Intermediate" "Advanced" ) ;
            sh:maxCount 1 ;
            sh:message "Choose from the list; other values are kept." ;
            sh:name "Level" ;
            sh:order 11 ;
            sh:path schema:educationalLevel ;
            sh:severity sh:Warning ],
        [ sh:datatype xsd:string ;
            sh:name "Learning outcomes" ;
            sh:order 12 ;
            sh:path schema:teaches ],
        [ sh:datatype xsd:string ;
            sh:name "Prerequisites" ;
            sh:order 13 ;
            sh:path schema:competencyRequired ],
        [ sh:name "Authors" ;
