                        sh:class schema:DigitalDocument ;
                        sh:node form:DigitalDocument ] ) ;
            sh:order 17 ;
            sh:path schema:hasPart ],
        [ sh:class schema:VideoObject ;
            sh:maxCount 1 ;
            sh:name "Video" ;
            sh:node form:VideoObject ;
            sh:nodeKind sh:BlankNode ;
            sh:order 18 ;
            sh:path schema:video ],
        [ sh:class schema:Course ;
