form:HowTo a sh:NodeShape ;
    rdfs:label "Workflow page" ;
    sh:property [ sh:datatype xsd:string ;
            sh:group form:workflow ;
            sh:maxCount 1 ;
            sh:message "One title needed." ;
            sh:minCount 1 ;
            sh:name "Title" ;
            sh:order 1 ;
            sh:path schema:name ],
        [ dash:singleLine false ;
            sh:description "A question's wording; on other pages, the page's text in HTML, when not in sections." ;
            sh:group form:workflow ;
            sh:maxCount 1 ;
            sh:name "Text" ;
            sh:or ( form:PlainText form:HTMLText ) ;
            sh:order 2 ;
            sh:path schema:text ],
        [ sh:datatype xsd:string ;
            sh:group form:workflow ;
            sh:maxCount 1 ;
            sh:name "Heading of its page" ;
            sh:order 3 ;
            sh:path schema:headline ],
        [ sh:datatype xsd:string ;
            sh:group form:workflow ;
            sh:maxCount 1 ;
            sh:name "Summary" ;
            sh:order 4 ;
            sh:path schema:description ],
        [ sh:description "The kind of process flow step the page is, for a question's steps; their buttons are named by it." ;
            sh:group form:workflow ;
            sh:in ( glossary:VHP0000153 glossary:VHP0000154 glossary:VHP0000155 glossary:VHP0000156 glossary:VHP0000158 ) ;
            sh:maxCount 1 ;
            sh:message "Choose a process flow step from the list." ;
            sh:name "Process flow step" ;
            sh:nodeKind sh:IRI ;
            sh:order 5 ;
            sh:path schema:additionalType ;
            sh:severity sh:Warning ],
        [ sh:datatype xsd:string ;
            sh:description "\"disabled\": the button is shown but cannot be opened yet." ;
            sh:group form:workflow ;
            sh:maxCount 1 ;
            sh:name "Status" ;
            sh:order 6 ;
            sh:path schema:creativeWorkStatus ],
        [ sh:datatype xsd:integer ;
            sh:description "Button order on the parent page; 1 is first." ;
            sh:group form:workflow ;
            sh:maxCount 1 ;
            sh:name "Position" ;
            sh:order 7 ;
            sh:path schema:position ],
        [ sh:class schema:WebPageElement ;
            sh:description "Page sections, each with a heading, an HTML text and a position." ;
            sh:group form:parts ;
            sh:name "Sections" ;
            sh:node form:WebPageElement ;
            sh:nodeKind sh:BlankNode ;
            sh:order 1 ;
            sh:path schema:hasPart ],
        [ sh:class schema:HowTo ;
            sh:description "Each a page under this page's address; a question's are its process flow steps." ;
            sh:group form:parts ;
            sh:name "Steps" ;
            sh:node form:HowTo ;
            sh:nodeKind sh:IRI ;
            sh:order 2 ;
            sh:path schema:step ],
        [ sh:class schema:HowToTool ;
            sh:description "Each use of a tool or method on the page; names and descriptions come from their records." ;
            sh:group form:parts ;
            sh:name "Tools and methods" ;
            sh:node form:HowToTool ;
            sh:nodeKind sh:BlankNode ;
            sh:order 3 ;
            sh:path schema:tool ],
        [ sh:class schema:HowToSupply ;
            sh:description "Each use of a dataset on the page; names and descriptions come from their records." ;
            sh:group form:parts ;
            sh:name "Data" ;
            sh:node form:HowToSupply ;
            sh:nodeKind sh:BlankNode ;
            sh:order 4 ;
            sh:path schema:supply ],
        [ sh:class bioschemas:FormalParameter ;
            sh:description "What a step takes, such as an estimated daily intake." ;
            sh:group form:parts ;
            sh:name "Input" ;
            sh:node form:FormalParameter ;
            sh:nodeKind sh:BlankNode ;
            sh:order 5 ;
            sh:path bioschemas:input ],
        [ sh:class bioschemas:FormalParameter ;
            sh:description "What a step gives, such as an exposure calculation." ;
            sh:group form:parts ;
            sh:name "Output" ;
            sh:node form:FormalParameter ;
            sh:nodeKind sh:BlankNode ;
            sh:order 6 ;
            sh:path bioschemas:output ] ;
    sh:targetClass schema:HowTo .

