        [ sh:description "The address of the video's player, such as https://video.edu.nl/videos/embed/<id>." ;
            sh:maxCount 1 ;
            sh:message "The player's address needed." ;
            sh:minCount 1 ;
            sh:name "Player" ;
            sh:nodeKind sh:IRI ;
            sh:order 2 ;
            sh:path schema:embedUrl ],
        [ sh:maxCount 1 ;
            sh:name "Thumbnail" ;
            sh:nodeKind sh:IRI ;
            sh:order 3 ;
            sh:path schema:thumbnailUrl ],
        [ sh:datatype xsd:string ;
            sh:description "An ISO 8601 duration, such as PT5M38S." ;
            sh:maxCount 1 ;
            sh:name "Duration" ;
            sh:order 4 ;
            sh:path schema:duration ;
            sh:pattern "^P" ] ;
    sh:targetClass schema:VideoObject .

form:WebPage a sh:NodeShape ;
    rdfs:label "Page" ;
    sh:order 8 ;
    sh:property [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:name "Title" ;
            sh:order 1 ;
            sh:path schema:name ],
        [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:name "Description" ;
            sh:order 2 ;
            sh:path schema:description ],
        [ sh:maxCount 1 ;
            sh:name "Address elsewhere" ;
            sh:nodeKind sh:IRI ;
            sh:order 3 ;
            sh:path schema:url ],
        [ sh:class schema:DefinedTerm ;
            sh:description "A term whose kinds the page explains, such as Process Flow Step." ;
            sh:name "Terms explained" ;
            sh:order 4 ;
            sh:path schema:about ],
        [ sh:class schema:WebPageElement ;
            sh:description "Sections of a platform page, each with a heading, a text and a position; a section's own sections are its items." ;
            sh:name "Sections" ;
            sh:node form:WebPageElement ;
            sh:nodeKind sh:BlankNode ;
            sh:order 5 ;
            sh:path schema:hasPart ] ;
    sh:targetClass schema:WebPage ;
    form:path "pages" .

