form:WebPageElement a sh:NodeShape ;
    rdfs:label "Section" ;
    sh:property [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:name "Heading" ;
            sh:order 1 ;
            sh:path schema:name ],
        [ dash:singleLine false ;
            sh:maxCount 1 ;
            sh:name "Text" ;
            sh:or ( form:PlainText form:HTMLText ) ;
            sh:order 2 ;
            sh:path schema:text ],
        [ sh:datatype xsd:integer ;
            sh:maxCount 1 ;
            sh:name "Position" ;
            sh:order 3 ;
            sh:path schema:position ],
        [ sh:class schema:ImageObject ;
            sh:description "Shown after the text." ;
            sh:name "Figures" ;
            sh:node form:ImageObject ;
            sh:nodeKind sh:BlankNode ;
            sh:order 4 ;
            sh:path schema:image ],
        [ sh:class schema:VideoObject ;
            sh:name "Videos" ;
            sh:node form:VideoObject ;
            sh:nodeKind sh:BlankNode ;
            sh:order 5 ;
            sh:path schema:video ],
        [ sh:datatype xsd:string ;
            sh:description "\"hidden\": kept, but not shown." ;
            sh:maxCount 1 ;
            sh:name "Status" ;
            sh:order 6 ;
            sh:path schema:creativeWorkStatus ],
        [ sh:class schema:WebPageElement ;
            sh:description "Its own sections, shown as its items." ;
            sh:name "Sections" ;
            sh:node form:WebPageElement ;
            sh:nodeKind sh:BlankNode ;
            sh:order 7 ;
            sh:path schema:hasPart ],
        [ sh:description "The record the section presents: the fields of it the section shows; or, for a grant without them, the records that name it, such as its publications." ;
            sh:maxCount 1 ;
            sh:name "Presents" ;
            sh:or ( [ rdfs:label "Grant" ;
                        sh:class schema:MonetaryGrant ] [ rdfs:label "Organisation or project" ;
                        sh:class schema:Organization ] [ rdfs:label "Training material" ;
                        sh:class schema:LearningResource ] ) ;
            sh:order 8 ;
            sh:path schema:about ],
        [ sh:description "The fields of the record it presents that the section shows, such as its description or its research lines." ;
            sh:in ( schema:description schema:text schema:image schema:video schema:subjectOf schema:subOrganization schema:member schema:funding schema:funder schema:amount schema:identifier ) ;
            sh:message "Choose from the list; other values are kept." ;
            sh:name "Shows" ;
            sh:nodeKind sh:IRI ;
            sh:order 10 ;
            sh:path form:shows ;
            sh:severity sh:Warning ],
        [ sh:description "Where the section is read, such as a tutorial's section on the documentation site." ;
            sh:maxCount 1 ;
            sh:name "Address" ;
            sh:nodeKind sh:IRI ;
            sh:order 9 ;
            sh:path schema:url ] ;
    sh:targetClass schema:WebPageElement .

